renderer.valueExpression:
// The fields from which to calculate predominance
// The expression will return the alias of the predominant field
// percentile poc, HL, IIP
var fields = [
  { value: $feature.PR_POC, alias: "Persons of color" },
  { value: $feature.PR_Latine, alias: "Persons of Hispanic/Latine ethnic origin" },
  { value: $feature.PR_IndPOv, alias: "Persons with income below poverty" },
];

// Returns the predominant category as the alias
// defined in the fields array. If there is a tie,
// then both names are concatenated and used to
// indicate the tie

function getPredominantCategory(fieldsArray){
  var maxValue = -Infinity;
  var maxCategory = "";
  for(var k in fieldsArray){
    if(fieldsArray[k].value > maxValue){
      maxValue = fieldsArray[k].value;
      maxCategory = fieldsArray[k].alias;
    } else if (fieldsArray[k].value == maxValue){
      maxCategory = maxCategory + "/" + fieldsArray[k].alias;
    }
  }
  return IIF(maxValue < 0.80, "Not Qualified", maxCategory);
}

getPredominantCategory(fields);

var mvi = $feature["PR_MVI"];
var ej = $feature["PR_EJpops"];
When(
    mvi >= 0.8 && ej >= 0.8, 
    'Populations of concern for both environmental justice and health vulnerability', 
    mvi >= 0.8 && mvi > ej, 
    'Health vulnerable populations', 
    ej >= 0.8 && ej > mvi, 
    'Environmental justice populations', 
    'Not Qualified'
    );
